INSERT INTO `case_board_meetings` (`id`, `case_id`, `meeting_no`, `year`, `meeting_date`, `resolution`, `notes`, `created_at`, `seq`) VALUES (20, 'case-gb2a9g', 5, 2569, '2026-08-04', 'เปรียบเทียบปรับ', '(1) ผู้รับอนุญาตผลิตผลิตภัณฑ์สมุนไพร ไม่จัดให้มีฉลากและเอกสารกำกับผลิตภัณฑ์ตามที่ได้รับอนุญาตไว้ จำนวน 4 รายการ เข้าข่ายกระทำฝ่าฝืนพระราชบัญญัติผลิตภัณฑ์สมุนไพร พ.ศ.๒๕6๒ มาตรา 29(3) มีโทษตามมาตรา 98 ต้องระวางโทษปรับไม่เกินห้าหมื่นบาท เห็นควรเปรียบเทียบปรับผู้รับอนุญาตเป็นรายผลิตภัณฑ์ ผลิตภัณฑ์ละ 12,500 บาท จำนวน 4 ผลิตภัณฑ์ เป็นจำนวนเงินรวมทั้งสิ้น 50,000 บาท (ห้าหมื่นบาทถ้วน)\n(2) ผู้รับอนุญาตผลิตผลิตภัณฑ์สมุนไพร ไม่ควบคุมดูแลให้ผู้มีหน้าที่ปฏิบัติการ ทำหน้าที่ตามที่กำหนดในพระราชบัญญัตินี้ เข้าข่ายกระทำฝ่าฝืนพระราชบัญญัติผลิตภัณฑ์สมุนไพร พ.ศ.๒๕6๒ มาตรา 25 มีโทษตามมาตรา 96 ต้องระวางโทษปรับไม่เกินห้าพันบาท เห็นควรเปรียบเทียบปรับผู้รับอนุญาตเป็นรายผลิตภัณฑ์ ผลิตภัณฑ์ละ 5,000 บาท จำนวน 4 ผลิตภัณฑ์ เป็นจำนวนเงินรวมทั้งสิ้น 20,000 บาท (สองหมื่นบาทถ้วน)\n(3) ผู้มีหน้าที่ปฏิบัติการประจำสถานที่ผลิตผลิตภัณฑ์สมุนไพร ไม่ดูแลการปฏิบัติเกี่ยวกับการแสดงฉลากและเอกสารกำกับผลิตภัณฑ์ ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่คณะกรรมการประกาศกำหนด เข้าข่ายกระทำฝ่าฝืนพระราชบัญญัติผลิตภัณฑ์สมุนไพร พ.ศ.๒๕6๒ มาตรา 31(4) มีโทษตามมาตรา 99 ต้องระวางโทษปรับไม่เกินสองหมื่นบาท เห็นควรเปรียบเทียบปรับเป็นผู้มีหน้าที่ปฏิบัติการ เป็นรายผลิตภัณฑ์ ผลิตภัณฑ์ละ 5,000 บาท จำนวน 4 ผลิตภัณฑ์ เป็นจำนวนเงินรวมทั้งสิ้น 20,000 บาท (สองหมื่นบาทถ้วน)\nดังนั้น เห็นควรเปรียบเทียบปรับ\n- ผู้รับอนุญาต นายจำรูญ กลัดพันธุ์ จำนวน 70,000 บาท (เจ็ดหมื่นบาทถ้วน)\n- ผู้มีหน้าที่ปฏิบัติการ นางสาวธันยพร ช่างต่อ จำนวน 20,000 บาท (สองหมื่นบาทถ้วน)', '2026-08-21 09:56:45', 0);
