INSERT INTO `case_investigations` (`id`, `case_id`, `kind`, `date`, `place`, `result`, `created_at`, `seq`) VALUES (34, 'case-p37v4n', 'site', '2026-08-12', NULL, 'ตรวจสอบในระบบ NAS ไม่พบการขออนุญาตออกหน่วยเคลื่อนที่ในวันที่ 11 ธันวาคม 2568 ขั้นตอนต่อไปรายงานนายแพทย์สาธารณสุขจังหวัดนนทบุรีและส่งเรื่องไปยังกรมสนับสนุนบริการสุขภาพ(สถานพยาบาลตามกรณีตั้งอยู่ในเขตกรุงเทพมหานคร)', '2026-08-12 18:46:08', 0);
