INSERT INTO `case_investigations` (`id`, `case_id`, `kind`, `date`, `place`, `result`, `created_at`, `seq`) VALUES (38, 'case-pn6cyg', 'site', '2026-08-14', 'บริษัท ฮิพไทย จำกัด', 'ตรวจสอบ บริษัท ฮิพไทย จำกัด\nที่อยู่7/13 หมู่ 10 ซอยคลองถนน ถนนจันทร์ทองเอี่ยม ตำบล บ้านใหม่ อำเภอ บางใหญ่\nไม่พบสถานที่นำเข้าตามกรณีร้องเรียน\nสอบถามไปรษณีย์แจ้งว่าผู้ประกอบการย้ายออกไปนานแล้ว และตอนนี้ที่ตั้งดังกล่าวเป็นบ้านร้าง\n', '2026-08-15 14:47:29', 0);
INSERT INTO `case_investigations` (`id`, `case_id`, `kind`, `date`, `place`, `result`, `created_at`, `seq`) VALUES (39, 'case-c3uz7a', 'site', '2026-08-14', 'เลดี้ ฟลาวเวอร์', 'ตรวจสอบสถานที่ผลิต พบตัวอย่างฉลากผลิตภัณฑ์\nพบการกระทำผิดตาม พรบ.เครื่องสำอาง พ.ศ.2558', '2026-08-15 14:52:00', 0);
