INSERT INTO `case_investigations` (`id`, `case_id`, `kind`, `date`, `place`, `result`, `created_at`, `seq`) VALUES (62, 'case-tghqws', 'meeting', '2026-08-17', NULL, 'มีหนังสือขอความอนุเคราะห์ร่วมตรวจสอบกรณีร้องเรียนไปยังอำเภอเมืองนนทบุรี ลว 17 สิงหาคม 2569\nโดยส่งให้อำเภอนนทบุรี เซ็นรับเอกสารวันที่ 19 สค69', '2026-09-03 18:02:08', 0);
INSERT INTO `case_investigations` (`id`, `case_id`, `kind`, `date`, `place`, `result`, `created_at`, `seq`) VALUES (63, 'case-80dbd7', 'meeting', '2026-09-07', NULL, 'ผู้รับมอบอำนาจจากกรรมการ บริษัท ทรีมีลส์ จำกัด เข้าพบพนักงานเจ้าหน้าที่ ยอมรับว่าเป็นผู้ผลิต ผลิตภัณฑ์ตามกรณีร้องเรียน และยอมรับว่าผลิตภัณฑ์มีการแสดงฉลากไม่ถูกต้อง', '2026-09-07 14:53:18', 2);
