INSERT INTO `case_investigations` (`id`, `case_id`, `kind`, `date`, `place`, `result`, `created_at`, `seq`) VALUES (65, 'case-0d70a39d0869c489', 'meeting', '2026-09-03', NULL, 'นายชญานนท์ เนตรสว่าง ผู้ดำเนินการสถานพยาบาล และนางสาวเมธาวี จูงหัตถการสาธิต ผู้จัดการของสถานพยาบาล เข้าพบพนักงานเจ้าหน้าที่ ชี้แจงข้อเท็จจริงตามกรณีร้องเรียน ', '2026-09-07 14:58:07', 1);
