INSERT INTO `cases` (`id`, `etracking`, `letter_no`, `letter_date`, `post_no`, `post_date`, `title`, `source_id`, `product`, `product_license`, `bounty_amount`, `bounty_requested`, `bounty_first_name`, `bounty_last_name`, `bounty_no`, `description`, `status_code`, `complainant_name`, `complainant_phone`, `complainant_email`, `complainant_address`, `complainant_anonymous`, `complainant_channel_id`, `respondent_licensee`, `respondent_business`, `respondent_address`, `respondent_license_no`, `respondent_district_id`, `respondent_subdistrict_id`, `inv_site_visit_date`, `inv_site_place`, `inv_site_result`, `inv_meeting_date`, `inv_meeting_place`, `inv_meeting_summary`, `board_meeting_no`, `board_year`, `board_meeting_date`, `board_resolution`, `board_notes`, `has_board`, `lock_overridden`, `cancel_reason`, `closed_at`, `returned`, `return_reason`, `is_draft`, `created_by`, `created_by_user_id`, `created_at`, `assigned_at`, `assigned_by`, `sla_extension_days`, `doc_no`, `doc_date`, `problem_other`, `assign_sla_waived`, `wants_followup`) VALUES ('case-gb2a9g', '4', '8523', '2026-05-15', '680', '2026-05-19', 'ห้างขายยาสองหมอโอสถ', NULL, 'น้ำมันสีเขียวสิรินุช ในห้างขายยาตราหมอโอสถ ปลอมทะเบียน G44/63  เป็นของปลอม 1 ขวด แท้ 1 ขวด', NULL, NULL, 0, NULL, NULL, NULL, NULL, '04', 'คุณบุรินทร์ นวลแก้ว 02-003-5548,085-0741411', NULL, NULL, NULL, 0, NULL, 'นายจำรูญ กลัดพันธุ์', 'ห้างขายยาสองหมอโอสถ', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, 2569, '2026-08-04', 'เปรียบเทียบปรับ', '(1) ผู้รับอนุญาตผลิตผลิตภัณฑ์สมุนไพร ไม่จัดให้มีฉลากและเอกสารกำกับผลิตภัณฑ์ตามที่ได้รับอนุญาตไว้ จำนวน 4 รายการ เข้าข่ายกระทำฝ่าฝืนพระราชบัญญัติผลิตภัณฑ์สมุนไพร พ.ศ.๒๕6๒ มาตรา 29(3) มีโทษตามมาตรา 98 ต้องระวางโทษปรับไม่เกินห้าหมื่นบาท เห็นควรเปรียบเทียบปรับผู้รับอนุญาตเป็นรายผลิตภัณฑ์ ผลิตภัณฑ์ละ 12,500 บาท จำนวน 4 ผลิตภัณฑ์ เป็นจำนวนเงินรวมทั้งสิ้น 50,000 บาท (ห้าหมื่นบาทถ้วน)\n(2) ผู้รับอนุญาตผลิตผลิตภัณฑ์สมุนไพร ไม่ควบคุมดูแลให้ผู้มีหน้าที่ปฏิบัติการ ทำหน้าที่ตามที่กำหนดในพระราชบัญญัตินี้ เข้าข่ายกระทำฝ่าฝืนพระราชบัญญัติผลิตภัณฑ์สมุนไพร พ.ศ.๒๕6๒ มาตรา 25 มีโทษตามมาตรา 96 ต้องระวางโทษปรับไม่เกินห้าพันบาท เห็นควรเปรียบเทียบปรับผู้รับอนุญาตเป็นรายผลิตภัณฑ์ ผลิตภัณฑ์ละ 5,000 บาท จำนวน 4 ผลิตภัณฑ์ เป็นจำนวนเงินรวมทั้งสิ้น 20,000 บาท (สองหมื่นบาทถ้วน)\n(3) ผู้มีหน้าที่ปฏิบัติการประจำสถานที่ผลิตผลิตภัณฑ์สมุนไพร ไม่ดูแลการปฏิบัติเกี่ยวกับการแสดงฉลากและเอกสารกำกับผลิตภัณฑ์ ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่คณะกรรมการประกาศกำหนด เข้าข่ายกระทำฝ่าฝืนพระราชบัญญัติผลิตภัณฑ์สมุนไพร พ.ศ.๒๕6๒ มาตรา 31(4) มีโทษตามมาตรา 99 ต้องระวางโทษปรับไม่เกินสองหมื่นบาท เห็นควรเปรียบเทียบปรับเป็นผู้มีหน้าที่ปฏิบัติการ เป็นรายผลิตภัณฑ์ ผลิตภัณฑ์ละ 5,000 บาท จำนวน 4 ผลิตภัณฑ์ เป็นจำนวนเงินรวมทั้งสิ้น 20,000 บาท (สองหมื่นบาทถ้วน)\nดังนั้น เห็นควรเปรียบเทียบปรับ\n- ผู้รับอนุญาต นายจำรูญ กลัดพันธุ์ จำนวน 70,000 บาท (เจ็ดหมื่นบาทถ้วน)\n- ผู้มีหน้าที่ปฏิบัติการ นางสาวธันยพร ช่างต่อ จำนวน 20,000 บาท (สองหมื่นบาทถ้วน)', 1, 1, NULL, NULL, 0, NULL, 0, 'admin', 21, '2026-07-20', NULL, 'admin', 0, NULL, NULL, NULL, 0, 0);
